var Registry  = require("./registry.js");

Registry.setLocator("taf.tafregistry.QueryObj@tcp -h regsitry1.taf.com -p 17890:tcp -h registry2.qq.com -p 17890");
Registry.findObjectById4Any("taf.tafregistry.QueryObj").then(function (data){
    var endpoints = data.response.arguments.activeEp;
    console.log("SUCCESS33", data.response.arguments.activeEp.value.length);
    console.log("SUCCESS44", data.response.arguments.activeEp.length);
    console.log("SUCCESS55", endpoints.length);

    for (var i = 0; i < endpoints.length; i++) {
        console.log("ENDPOINT:", endpoints.value[i].host, endpoints.value[i].port);
    }
}, function (){ console.log("ERROR"); });